        "action_cost" : null,
        "bulk" : null,
        "category" : "feat",
        "description" : "<p>Il en faut plus pour vous tuer que la plupart des gens. Vous mourez de l’état mourant à mourant 5 plutôt qu’à mourant 4.</p>",
        "element_type" : "DON 1",
